update ${tableName}
set last_sync_id = #{syncId},
    sort_no = case version_id
        when #{i.versionId} then #{i.sortNo} 
        else sort_no end,
    update_by = #{updateBy},
    update_time = date_add(utc_timestamp(), interval 8 hour),
    update_time_utc = utc_timestamp()
where version_id in
#{i.versionId}

