select , payload
from ${tableName}
where last_sync_id = #{syncId}
order by sort_no, version_id

select 
from ${tableName}

    and item_key = #{item.itemKey}
    and title like concat('%', #{item.title}, '%')
    and category = #{item.category}
    and access_level = #{item.accessLevel}
    and publish_date = #{item.publishDate}
    and last_sync_id = #{item.lastSyncId}

order by version_id desc

